302:     let u = 1;
303:     if (this.doors.left) u += 1;
304:     if (this.doors.right) u += 1;
305:     if (this.lights.left || this.lights.right) u += .55;
306:     if (this.camOpen) u += .5;
307:     if (this.lureT > 0) u += .35;
308:     this.usage = u;
309:   }
