311:   _updatePower(dt) {
312:     const base = .135 * this.levels.drain;
313:     let drain = base;
314:     if (this.doors.left) drain += .185;
315:     if (this.doors.right) drain += .185;
316:     if (this.lights.left) drain += .12;
317:     if (this.lights.right) drain += .12;
318:     if (this.camOpen) drain += .115;
319:     this.power -= drain * dt;
320:     if (this.power <= 0) {
321:       this.power = 0;
322:       this._beginBlackout();
323:     }
324:   }
