341:   _updateBlackout(dt) {
342:     this.blackoutT += dt;
343:     if (this.blackoutT > 2.2 && !this._musicStarted) {
344:       this._musicStarted = true;
345:       this.audio.musicBox();
346:       this.events.onMessage?.('You are out of power.');
347:     }
348:     if (this.blackoutT > 11.5 && !this.finished) {
