430:   _updateFoxy(dt) {
431:     const f = this.foxy;
432:     if (f.running) {
433:       f.runT += dt;
434:       if (f.runT > 1.75) {
435:         if (this.doors.left) {
436:           f.running = false;
437:           f.stage = 0;
438:           f.timer = 18;
439:           this.audio.thud({ gain: .32, pan: -.8, low: true });
440:           this.audio.door(false, -.8);
441:           this.audio.knock(-.8);
442:           this.events.onFoxyBlocked?.();
443:         } else {
444:           this._kill('foxy');
445:         }
446:       }
447:       return;
448:     }
449:     if (this.camOpen && this.cam === '1C') {
450:       f.timer = Math.max(f.timer, 9);
451:       // watching keeps him at bay
452:       if (f.stage === 3) f.timer = Math.max(f.timer, 6);
453:     }
454:     if (f.stage >= 3) {
455:       f.timer -= dt;
456:       if (f.timer <= 0) {
457:         f.running = true;
458:         f.runT = 0;
459:         this.audio.foxyRun(-.9);
