34: /* ------------------------------------------------------------ textures */
35: let _curtainCache = {};
36: function curtainTexture(base, dark, light, stars) {
37:   const key = base + (stars ? 's' : '');
38:   if (_curtainCache[key]) return _curtainCache[key];
39:   const w = 512, h = 512, c = document.createElement('canvas');
40:   c.width = w; c.height = h;
41:   const x = c.getContext('2d');
42:   x.fillStyle = base; x.fillRect(0, 0, w, h);
43:   const n = 26, sw = w / n;
44:   for (let i = 0; i < n; i++) {
45:     const g = x.createLinearGradient(i * sw, 0, (i + 1) * sw, 0);
46:     g.addColorStop(0, dark);
47:     g.addColorStop(.35, light);
48:     g.addColorStop(.6, base);
49:     g.addColorStop(1, dark);
50:     x.fillStyle = g;
51:     x.fillRect(i * sw, 0, sw + 1, h);
52:     x.fillStyle = 'rgba(0,0,0,.18)';
53:     x.fillRect(i * sw, 0, 3, h);
54:   }
55:   if (stars) {
56:     for (let i = 0; i < 26; i++) {
57:       const sx = 30 + rand() * (w - 60), sy = 20 + rand() * (h - 40), r = 5 + rand() * 7;
58:       x.save(); x.translate(sx, sy); x.rotate(rand() * .6);
59:       x.fillStyle = `rgba(232,196,120,${.5 + rand() * .35})`;
60:       x.beginPath();
61:       for (let j = 0; j < 10; j++) {
62:         const a = -Math.PI / 2 + j * Math.PI / 5, rr = j % 2 ? r * .45 : r;
63:         x[j ? 'lineTo' : 'moveTo'](Math.cos(a) * rr, Math.sin(a) * rr);
64:       }
65:       x.closePath(); x.fill(); x.restore();
66:     }
67:   }
68:   const t = finish(c, 1, 1);
69:   _curtainCache[key] = t;
70:   return t;
71: }
72: 
73: function bannerTexture() {
74:   const w = 1024, h = 128, c = document.createElement('canvas');
75:   c.width = w; c.height = h;
76:   const x = c.getContext('2d');
77:   x.clearRect(0, 0, w, h);
78:   // string
79:   x.strokeStyle = 'rgba(230,220,190,.55)'; x.lineWidth = 3;
80:   x.beginPath(); x.moveTo(0, 30); x.quadraticCurveTo(w / 2, 64, w, 30); x.stroke();
81:   const cols = ['#c9463a', '#e6c063', '#6f9c72', '#d8d0b8'];
82:   for (let i = 0; i < 22; i++) {
83:     const px = 22 + i * 46, py = 34 + Math.sin(i / 21 * Math.PI) * 26;
84:     x.fillStyle = cols[i % 4];
85:     x.beginPath(); x.moveTo(px, py); x.lineTo(px + 34, py); x.lineTo(px + 17, py + 34); x.closePath(); x.fill();
86:   }
87:   const t = new THREE.CanvasTexture(c);
88:   t.colorSpace = THREE.SRGBColorSpace;
89:   return t;
90: }
