178:   _glow(color, size, opacity = .5) {
179:     const s = new THREE.Sprite(new THREE.SpriteMaterial({
180:       map: this.glowTex, color, transparent: true, opacity,
181:       blending: THREE.AdditiveBlending, depthWrite: false
182:     }));
183:     s.scale.set(size, size, 1);
184:     return s;
