200:   _shell(room, w, d, h, opts = {}) {
201:     const g = room.group;
202:     const wall = new THREE.MeshStandardMaterial({
203:       map: wallTexture(), normalMap: normalTexture('plaster', 2.0),
204:       normalScale: new THREE.Vector2(.6, .6), roughness: .94, envMapIntensity: .16
205:     });
206:     const wains = new THREE.MeshStandardMaterial({
207:       map: wainscotTexture(), normalMap: normalTexture('wood', 1.8),
208:       normalScale: new THREE.Vector2(.55, .55), roughness: .82, envMapIntensity: .22
209:     });
210:     const floorM = new THREE.MeshStandardMaterial({
211:       map: floorTexture(), normalMap: normalTexture('tile', 1.6),
212:       normalScale: new THREE.Vector2(.8, .8), roughness: .32, metalness: .18, envMapIntensity: .7
213:     });
214:     const ceil = new THREE.MeshStandardMaterial({
215:       map: ceilingTexture(), normalMap: normalTexture('tile', 1.3),
216:       normalScale: new THREE.Vector2(.7, .7), roughness: 1, envMapIntensity: .08
217:     });
218:     const trim = new THREE.MeshStandardMaterial({ color: 0x2a2118, roughness: .7 });
219:     g.add(plane(w, d, floorM, 0, 0, 0, -Math.PI / 2));
220:     g.add(plane(w, d, ceil, 0, h, 0, Math.PI / 2));
221:     // four walls facing inward
222:     g.add(plane(w, h, wall, 0, h / 2, -d / 2, 0, 0));
223:     g.add(plane(w, h, wall, 0, h / 2, d / 2, 0, Math.PI));
224:     g.add(plane(d, h, wall, -w / 2, h / 2, 0, 0, Math.PI / 2));
225:     g.add(plane(d, h, wall, w / 2, h / 2, 0, 0, -Math.PI / 2));
226:     // wainscot bands on all four walls
227:     const wy = .46;
228:     g.add(plane(w, .92, wains, 0, wy, -d / 2 + .011, 0, 0));
229:     g.add(plane(w, .92, wains, 0, wy, d / 2 - .011, 0, Math.PI));
230:     g.add(plane(d - .02, .92, wains, -w / 2 + .011, wy, 0, 0, Math.PI / 2));
231:     g.add(plane(d - .02, .92, wains, w / 2 - .011, wy, 0, 0, -Math.PI / 2));
232:     // chair rail + baseboard
233:     for (const [len, x, z, ry] of [[w, 0, -d / 2 + .02, 0], [w, 0, d / 2 - .02, Math.PI], [d, -w / 2 + .02, 0, Math.PI / 2], [d, w / 2 - .02, 0, -Math.PI / 2]]) {
234:       g.add(box(len, .06, .05, trim, x, .94, z));
235:       g.add(box(len, .13, .05, trim, x, .07, z));
236:     }
237:     room.mats = { wall, wains, floorM, ceil, trim };
238:     return room;
239:   }
