241:   _lightBar(room, x, y, z, len = .8, color = 0xffe8bd, intensity = 5.5, dist = 9) {
242:     const g = room.group;
243:     const fixture = box(len, .05, .22, new THREE.MeshStandardMaterial({ color: 0x2a2721, roughness: .6 }), x, y + .045, z);
244:     const tube = box(len * .82, .03, .15, new THREE.MeshStandardMaterial({
245:       color: 0x1a1814, emissive: color, emissiveIntensity: 1.6, roughness: .5
246:     }), x, y, z);
247:     g.add(fixture, tube);
248:     const p = new THREE.PointLight(color, intensity, dist, 1.6);
249:     p.position.set(x, y - .12, z);
250:     g.add(p);
251:     const halo = this._glow(color, 1.3, .4);
252:     halo.position.set(x, y - .08, z);
253:     g.add(halo);
254:     return p;
255:   }
