257:   _poster(room, kind, x, y, z, ry, s = 1) {
258:     const p = plane(.62 * s, .82 * s, new THREE.MeshStandardMaterial({ map: posterTexture(kind), roughness: .92 }), x, y, z, 0, ry);
259:     room.group.add(p);
260:     return p;
