263:   _addActor(room, type, x, y, z, rotY = 0, scale = 1) {
264:     const a = makeAnimatronic(type);
265:     a.group.position.set(x, y, z);
266:     a.group.rotation.y = rotY;
267:     a.group.scale.setScalar(scale);
268:     a.group.traverse(o => { if (o.isMesh) o.castShadow = false; });
269:     a.userData = { baseY: y, baseHeadRX: a.head.rotation.x, baseRotY: rotY };
270:     room.group.add(a.group);
271:     room.actors[type] = a;
272:     return a;
273:   }
