794:   /* ------------------------------------------------------------ burst fx */
795:   _buildBurstOverlay() {
796:     const ov = document.createElement('canvas');
797:     ov.width = W; ov.height = H;
798:     ov.className = 'feed-burst';
799:     ov.setAttribute('aria-hidden', 'true');
800:     this.canvas.parentNode.appendChild(ov);
801:     this.burst = ov;
802:     this.burstCtx = ov.getContext('2d');
803:     this.burstT = 0;
804:   }
805: 
806:   drawStaticBurst(amount = 1) {
807:     if (!this.ok || !this.burstCtx) return;
808:     const x = this.burstCtx;
809:     x.clearRect(0, 0, W, H);
810:     x.globalAlpha = Math.min(.8, .3 + .18 * amount);
811:     for (let i = 0; i < 26 * amount; i++) {
812:       const y = Math.random() * H, h = 1 + Math.random() * 3, dx = (Math.random() - .5) * 46;
813:       x.fillStyle = `rgba(255,255,255,${.25 + Math.random() * .5})`;
814:       x.fillRect(dx, y, W * (.3 + Math.random() * .7), h);
815:     }
816:     x.globalAlpha = 1;
817:     this.burstT = Math.max(this.burstT, .16 + .05 * amount);
818:   }
819: 
