770: /* Derive a tangent-space normal map from a height source. This is what makes
771:    the plaster, wood and steel catch the light on a high-DPI phone screen. */
772: function normalFromSource(src, strength, repeat) {
773:   const w = src.width, h = src.height;
774:   const read = canvas(w, h), rx = read.getContext('2d');
775:   rx.drawImage(src, 0, 0);
776:   const data = rx.getImageData(0, 0, w, h).data;
777:   const out = canvas(w, h), ox = out.getContext('2d');
778:   const img = ox.createImageData(w, h);
779:   const at = (xx, yy) => data[((((yy + h) % h) * w + ((xx + w) % w)) * 4)] / 255;
780:   for (let y = 0; y < h; y++) {
781:     for (let x = 0; x < w; x++) {
782:       const dx = (at(x + 1, y) - at(x - 1, y)) * strength;
783:       const dy = (at(x, y + 1) - at(x, y - 1)) * strength;
784:       let nx = -dx, ny = -dy, nz = 1;
785:       const l = Math.hypot(nx, ny, nz) || 1;
786:       nx /= l; ny /= l; nz /= l;
787:       const i = (y * w + x) * 4;
788:       img.data[i] = (nx * .5 + .5) * 255;
789:       img.data[i + 1] = (ny * .5 + .5) * 255;
790:       img.data[i + 2] = (nz * .5 + .5) * 255;
791:       img.data[i + 3] = 255;
792:     }
793:   }
794:   ox.putImageData(img, 0, 0);
795:   const t = new THREE.CanvasTexture(out);
796:   t.wrapS = t.wrapT = THREE.RepeatWrapping;
797:   if (repeat) t.repeat.copy(repeat);
798:   t.anisotropy = 8;
799:   t.colorSpace = THREE.NoColorSpace;
800:   return t;
801: }
802: const normalCache = new Map();
803: export function normalTexture(kind = 'plaster', strength = 2.2) {
804:   const key = kind + '|' + strength;
805:   if (normalCache.has(key)) return normalCache.get(key);
806:   const bump = bumpTexture(kind);
807:   const t = normalFromSource(bump.image, strength, bump.repeat);
808:   normalCache.set(key, t);
809:   return t;
810: }
